u skucode, name,brand, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number() over (partition by marketplace_sku order by length(ifnull(Category_Code,\'\')) desc ) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 ) pid on lower(fi.sku) = lower(pid.skucode) left join (select * from (select commonsku skucode, name,brand, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number() over (partition by commonsku order by length(ifnull(Category_Code,\'\')) desc ) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 ) cid on lower(fi.sku) = lower(cid.skucode) WHERE NULLIF(Reverse_Pickup_Created_Date, \"\") IS NOT NULL and lower(Order_Status) like \'%cancel%\' ; Create Or Replace Table `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` as SELECT pincode ,marketplace ,source ,order_id ,reference_code ,phone ,name ,email ,SHIPPING_LAST_UPDATE_DATE ,sku ,Marketplace_sku ,product_id ,product_name ,currency ,city ,state ,ORDER_STATUS ,invoiceCode ,invoiceDate ,initial_order_date ,order_date ,shipping_price ,SUBORDER_QUANTITY ,discount ,tax ,SELLING_PRICE ,shippingPackageCode ,shippingPackageStatus ,saleOrderItemCode ,SALES_ORDER_ITEM_ID ,AWB ,warehouse_name ,payment_mode ,payment_method ,courier ,shipping_status ,shippedQuantity ,Dispatch_date ,Delivered_Date ,return_flag ,return_quantity ,cancelled_quantity ,new_customer_flag ,acquisition_product ,days_in_shipment ,FINAL_MARKETPLACE ,MARKETPLACE_SEGMENT ,TYPE_OF_SALE ,Mode_of_Business1 ,Mode_Of_Business2 FROM `MapleMonk.zouk_UNICOMMERCE_fact_items_intermediate_final` WHERE NOT (TRIM(UPPER(CONCAT(ifnull(reference_code,\"\"),(ifnull(saleOrderItemCode,\"\"))))) IN ( SELECT DISTINCT TRIM(UPPER(CONCAT(ifnull(reference_code,\"\"),(ifnull(sale_Order_Item_Code,\"\"))))) FROM MapleMonk.zouk_new_unicommerce_factitems_intermediate )) UNION ALL SELECT pincode, Marketplace, Marketplace as Source, Order_Id, o.reference_code, Phone, Name, email, CAST(NULLIF(Shipping_Last_Update_Date, \"\") AS DATETIME) as Shipping_Last_Update_Date, SKU, marketplace_sku, product_id, Product_name, currency, city, State, case when os.sale_order_item_code is not null then \'RETURNED\' else o.ORDER_STATUS end as ORDER_STATUS, Invoice_Code as invoiceCode, Invoice_Date as invoiceDate, CAST(NULLIF(Initial_Order_Date, \"\") AS DATETIME) as Initial_Order_Date, CASE WHEN LOWER(TYPE_OF_SALE) LIKE \'%primary%\' THEN o.invoice_Date ELSE o.order_date END AS order_date, shipping_price, Quantity as suborder_quantity, discount, tax, Selling_Price, Shipping_Package_Code as shippingPackageCode, Shipping_Package_Status as shippingPackageStatus, o.Sale_order_item_code as saleOrderItemCode, null as sales_order_item_id, AWB, warehouse_name, payment_mode, null as Payment_method, COURIER, Shipping_Status, null as shippedQuantity, CAST(NULLIF(Dispatch_Date, \"\") AS DATETIME) as Dispatch_Date, CAST(NULLIF(Delivered_Date, \"\") AS DATETIME) as Delivered_Date, null as return_flag, null as return_quantity, null as cancelled_quantity, null as new_customer_flag, null as acquisition_product, null as days_in_shipment, FINAL_MARKETPLACE, MARKETPLACE_SEGMENT, TYPE_OF_SALE, Mode_Of_Business1, Mode_Of_Business2 FROM MapleMonk.zouk_new_unicommerce_factitems_intermediate o left join ( select reference_code ,sale_order_item_code from maplemonk.zouk_UNICOMMERCE_RETURNS_INTERMEDIATE qualify row_number() over(partition by lower(reference_code),lower(sale_order_item_code) order by 1) =1 )os on lower(o.reference_code) = lower(os.reference_code) and loweR(os.sale_order_item_code) = lower(o.sale_Order_Item_Code) ; create or replace table maplemonk.zouk_customerID_test_Final as with new_phone_numbers as ( select contact_num ,9700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct SUBSTR(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) as contact_num from `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` ) a ), int as ( select contact_num,email,coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email,maple_monk_id,9800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10)) as contact_num, e.email,maple_monk_id from ( select replace(phone,\' \',\'\') as contact_num,email from `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` ) e left join new_phone_numbers p on p.contact_num = SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) ) a ) b ) select contact_num,email,case when email is not null and email <> \'\' then min(maple_monk_id) over (partition by email ) else maple_monk_id end maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` as select coalesce(c.maple_monk_id,c.maple_monk_id) customer_id, o.*, min(order_date) over(partition by coalesce(c.maple_monk_id,c.maple_monk_id)) as acquisition_date from `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` o left join (select distinct contact_num phone,maple_monk_id from maplemonk.zouk_customerID_test_Final )c on replace(c.phone,\' \',\'\') = replace(o.phone,\' \',\'\') where o.order_date is not null; CREATE OR REPLACE TABLE `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` as select fi.*, upper(coalesce(p.Brand,pid.Brand,cid.Brand)) AS Brand, coalesce(p.SKUCODE,pid.skucode,pid.skucode,fi.SKU) AS SKU_CODE, coalesce(p.name, pid.name,cid.name,fi.product_name) as PRODUCT_NAME_Final, Upper(coalesce(p.CATEGORY,pid.CATEGORY,cid.CATEGORY)) AS Product_Category, Upper(coalesce(p.SUB_CATEGORY,pid.SUB_CATEGORY,cid.SUB_CATEGORY)) AS Product_Sub_Category, Upper(coalesce(p.collection,pid.collection,cid.collection)) AS collection, Upper(coalesce(p.print,pid.print,cid.print)) AS print, Upper(coalesce(p.category_code,pid.category_code,cid.category_code)) AS category_code, Upper(coalesce(p.product_type,pid.product_type,cid.product_type)) AS product_type, (coalesce(p.BAU_OFFLINE,pid.BAU_OFFLINE,cid.BAU_OFFLINE)) AS BAU_OFFLINE, (coalesce(p.BAU_ONLINE,pid.BAU_ONLINE,cid.BAU_ONLINE)) AS BAU_ONLINE, (coalesce(p.TAX_RATE,pid.TAX_RATE,cid.TAX_RATE)) AS FINAL_TAX_RATE, Upper(coalesce(p.commonsku,pid.commonsku,cid.commonsku)) AS commonsku, Upper(coalesce(pid.category_code,cid.category_code)) AS child_category_code, latest.updated_order_status, latest.status_date from `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` fi left join (select * from (select marketplace_sku skucode, name,brand, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number() over (partition by marketplace_sku order by length(ifnull(Category_Code,\'\')) desc ) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 ) p on lower(fi.Marketplace_sku) = lower(p.skucode) left join (select * from (select marketplace_sku skucode, name,brand, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number() over (partition by marketplace_sku order by length(ifnull(Category_Code,\'\')) desc ) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 ) pid on lower(fi.sku) = lower(pid.skucode) left join (select * from (select commonsku skucode, name,brand, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number() over (partition by commonsku order by length(ifnull(Category_Code,\'\')) desc ) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 ) cid on lower(fi.sku) = lower(cid.skucode) LEFT JOIN ( SELECT Shipping_Package_Code, Display_Order_Code, time_stamp AS status_date, new_value AS updated_order_status FROM ( SELECT Shipping_Package_Code, Display_Order_Code, time_stamp, new_value, ROW_NUMBER() OVER ( PARTITION BY Shipping_Package_Code, Display_Order_Code, DATE(time_stamp) ORDER BY time_stamp DESC ) AS rn FROM `MapleMonk.zouk_db_get_shipping_package_timeline` ) WHERE rn = 1 ) latest ON LOWER(fi.reference_code) = LOWER(latest.Display_Order_Code) AND LOWER(fi.ShippingPackageCode) = LOWER(latest.Shipping_Package_Code) ;",
